    #[test]
    fn apply_compaction_leaves_no_tmp_residue() {
        // L-27: the atomic rewrite (temp + fsync + rename) must not leave a
        // .tmp file behind, and the rewritten file must round-trip.
        let dir = temp_dir();
        let mut manager = SessionStore::new(&dir);
        manager.create_session("llama3.2".to_string(), 32768, "/".to_string()).unwrap();
        manager
            .append_message(None, AgentMessage::user("first message".to_string()))
            .unwrap();
        manager
            .append_message(None, AgentMessage::assistant("first reply".to_string(), String::new(), Vec::new(), None))
            .unwrap();

        let cut = manager.entries().len();
        manager
            .apply_compaction("summary".to_string(), cut, 100)
            .unwrap();

        let sessions_dir = manager.sessions_dir();
        let tmp_files: Vec<_> = fs::read_dir(sessions_dir)
            .unwrap()
            .filter_map(std::result::Result::ok)
            .filter(|e| e.file_name().to_string_lossy().ends_with(".tmp"))
            .collect();
        assert!(tmp_files.is_empty(), "no .tmp residue: {tmp_files:?}");

        // The rewritten file must contain the compaction entry.
        let path = manager.current_session_path.clone().unwrap();
        let content = fs::read_to_string(&path).unwrap();
        assert!(content.contains("summary"), "rewritten file has the compaction: {content}");
    }

    #[test]
    fn apply_compaction_propagates_rewrite_failure() {
        // L-28: a rewrite failure (here: unwritable path) must surface as Err,
        // never be swallowed. True serialization failures are unconstructible —
        // every SessionEntry field serializes infallibly — so this exercises
        // the same propagation path.
        let dir = temp_dir();
        let mut manager = SessionStore::new(&dir);
        manager.create_session("llama3.2".to_string(), 32768, "/".to_string()).unwrap();
        manager
            .append_message(None, AgentMessage::user("hello".to_string()))
            .unwrap();

        // Point the store at a directory that does not exist: File::create of
        // the temp file fails, and the error must propagate out of apply_compaction.
        manager.current_session_path = Some(dir.join("no-such-dir").join("session.jsonl"));
        let result = manager.apply_compaction("summary".to_string(), 2, 100);
        assert!(result.is_err(), "rewrite failure must propagate: {result:?}");
    }

