    #[test]
    fn system_prompt_cache_roundtrip() {
        let dir = temp_dir();
        let mut manager = SessionStore::new(&dir);
        manager.create_session("llama3.2".to_string(), 32768, "/".to_string()).unwrap();
        assert_eq!(manager.cached_system_prompt(), "");
        assert_eq!(manager.cached_system_tokens(), 0);

        manager.set_system_prompt("You are a helpful assistant.".to_string());
        assert_eq!(manager.cached_system_prompt(), "You are a helpful assistant.");

        // Mirrors estimate_tokens_from_messages for a system message:
        // role label + content at the heuristic ratio.
        let est = TokenEstimator::heuristic();
        let expected = est.estimate_tokens("system") + est.estimate_tokens("You are a helpful assistant.");
        assert_eq!(manager.cached_system_tokens(), expected);
    }

    #[test]
    fn system_prompt_tokens_reestimated_after_calibration() {
        let dir = temp_dir();
        let mut manager = SessionStore::new(&dir);
        manager.create_session("llama3.2".to_string(), 32768, "/".to_string()).unwrap();
        manager.set_system_prompt("s".repeat(4000));
        let heuristic_tokens = manager.cached_system_tokens();

        // An assistant message with usage calibrates the ratio to 2.0
        // (base = 4000 context + 4000 system chars = 8000 → 8000/4000), and
        // the recompute re-estimates the cached system prompt with the new
        // ratio.
        manager
            .append_message(
                None,
                AgentMessage::assistant(
                    "a".repeat(4000),
                    String::new(),
                    Vec::new(),
                    Some(Usage {
                        prompt_tokens: 4000,
                        completion_tokens: 10,
                        total_tokens: 4010,
                    }),
                ),
            )
            .unwrap();

        let est = manager.cached_estimator();
        assert!((est.chars_per_token() - 2.0).abs() < f64::EPSILON);
        let expected = est.estimate_tokens("system") + est.estimate_tokens("s".repeat(4000).as_str());
        assert_eq!(manager.cached_system_tokens(), expected);
        assert!(manager.cached_system_tokens() > heuristic_tokens);
    }

